import{_ as n,C as s,o as i,c as l,a2 as e,j as a,a as r,E as d}from"./chunks/framework.BSl-aDiU.js";const _=JSON.parse('{"title":"1. Overview","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/overview.md","filePath":"gdd/overview.md"}'),h={name:"gdd/overview.md"},g={id:"_1-1-pitch",tabindex:"-1"};function p(c,t,f,u,m,b){const o=s("Badge");return i(),l("div",null,[t[3]||(t[3]=e('<h1 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Prototype Test</td></tr><tr><td><strong>Genre</strong></td><td>Puzzle · colour-matching auto-shooter</td></tr><tr><td><strong>Platform</strong></td><td>Web (mobile portrait first)</td></tr><tr><td><strong>Engine</strong></td><td>Phaser 4, TypeScript, Vite</td></tr><tr><td><strong>Session</strong></td><td>1–4 minutes per level</td></tr></tbody></table>',2)),a("h2",g,[t[0]||(t[0]=r("1.1 Pitch ",-1)),d(o,{type:"tip",text:"Live"}),t[1]||(t[1]=r()),t[2]||(t[2]=a("a",{class:"header-anchor",href:"#_1-1-pitch","aria-label":'Permalink to "1.1 Pitch <Badge type="tip" text="Live" />"'},"​",-1))]),t[4]||(t[4]=e('<p>A packed hangar of colour-coded fighter planes sits under an enemy armada. Tap a fighter to send it up to the flight zone, where it lines up under an enemy of <strong>its own colour</strong> and fires straight up. Enemies at the front shield the ones behind them, and every enemy shoots back at the flight zone, which has limited HP. Only fighters with a clear path out of the hangar can take off, and only 5 can fly at once. The puzzle is the <strong>order</strong>: launch the right colours for the front line in front of you, fast, and don&#39;t fill the sky with fighters that have nothing to shoot.</p><h2 id="_1-2-design-pillars" tabindex="-1">1.2 Design pillars <a class="header-anchor" href="#_1-2-design-pillars" aria-label="Permalink to &quot;1.2 Design pillars&quot;">​</a></h2><ol><li><strong>Every tap is a decision.</strong> The player never aims; all skill is in choosing which fighter to launch next, and launching it before enemy fire wears the flight zone down.</li><li><strong>Readable at a glance.</strong> Colour, a number (ammo on fighters, hit points on enemies) and a dimmed/bright state tell the whole story.</li><li><strong>Always fair.</strong> Every level is built so each colour&#39;s ammo exactly equals that colour&#39;s enemy hit points, and a solver proves every shipped level can be won (see <a href="./levels">Levels &amp; balance</a>).</li></ol><h2 id="_1-3-target-player" tabindex="-1">1.3 Target player <a class="header-anchor" href="#_1-3-target-player" aria-label="Permalink to &quot;1.3 Target player&quot;">​</a></h2><p>Casual mobile puzzle players who enjoy sort, jam and unblock games (one-thumb play, short sessions), plus a light shooter fantasy for visual payoff.</p><h2 id="_1-4-screen-at-a-glance" tabindex="-1">1.4 Screen at a glance <a class="header-anchor" href="#_1-4-screen-at-a-glance" aria-label="Permalink to &quot;1.4 Screen at a glance&quot;">​</a></h2><p>The 780 × 1688 portrait canvas is split top to bottom:</p><table tabindex="0"><thead><tr><th>Area</th><th>y range (px)</th><th>What happens there</th></tr></thead><tbody><tr><td>HUD</td><td>0–150</td><td>Level name, stage counter, back and restart buttons</td></tr><tr><td>Enemy area</td><td>150–880</td><td>The current stage&#39;s enemies or boss</td></tr><tr><td>Flight zone</td><td>880–1060</td><td>Launched fighters line up and shoot; shows <code>Flight zone n/5</code> and the zone&#39;s HP bar</td></tr><tr><td>Hangar board</td><td>1095–1660</td><td>The full grid of fighters and walls the player taps</td></tr></tbody></table>',8))])}const y=n(h,[["render",p]]);export{_ as __pageData,y as default};
